using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
using System.Text;
namespace PeopleHub.Tests;
/// <summary>ENT-002 staging and commit. SQLite only.</summary>
public class EmployeeImportBatchTests
{
 class User(bool allowed=true):ICurrentUser{public string Email=>"importer@example.local";public int? EmployeeId=>null;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>allowed&&p==Perm.EmpManage;}
 class Db(DbContextOptions o):AppDbContext(o){public bool Fail;public override async Task<int> SaveChangesAsync(CancellationToken ct=default){var n=await base.SaveChangesAsync(ct);if(Fail&&ChangeTracker.Entries<StagedEmployeeRow>().Any(e=>e.Entity.EmployeeId!=null))throw new InvalidOperationException("Fictional post-write failure");return n;}}
 static async Task<Db> Open(){var d=new Db(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.EnsureCreatedAsync();d.Add(new Branch{Id=1,Name="Fictional"});d.Add(new Department{Id=1,Name="Fictional"});d.Add(new JobTitle{Id=1,Name="Fictional"});d.Add(new Employee{Code="EXIST",FullName="Fictional existing",Email="existing@example.local",HireDate=new DateTime(2026,1,1),BranchId=1,DepartmentId=1,JobTitleId=1});await d.SaveChangesAsync();return d;}
 static EmployeeImportBatches S(AppDbContext d,bool allowed=true){var u=new User(allowed);var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c),new(d,u));}
 static byte[] Csv(params string[] rows)=>Encoding.UTF8.GetBytes(EmployeeImportValidation.Header+"\r\n"+string.Join("\r\n",rows));
 const string A="FIC-A,Fictional A,موظف أ,a@example.local,2027-01-01,1,1,1",B="FIC-B,Fictional B,,b@example.local,2027-01-02,1,1,1";
 [Fact]public async Task StagingCreatesNoEmployeeAndReusesBatchForSameFile(){await using var d=await Open();var id=await S(d).StageAsync(Csv(A,B));Assert.Equal(id,await S(d).StageAsync(Csv(A,B)));Assert.Equal(1,await d.Set<EmployeeImportBatch>().CountAsync());Assert.Equal(2,await d.Set<StagedEmployeeRow>().CountAsync());Assert.Equal(1,await d.Set<Employee>().CountAsync());}
 [Fact]public async Task AnyInvalidRowRejectsWholeFile(){await using var d=await Open();await Assert.ThrowsAsync<DomainException>(()=>S(d).StageAsync(Csv(A,"FIC-C,Fictional C,,existing@example.local,2027-01-01,1,1,1")));Assert.Equal(0,await d.Set<EmployeeImportBatch>().CountAsync());Assert.Equal(0,await d.Set<StagedEmployeeRow>().CountAsync());}
 [Fact]public async Task CommitCreatesAllEmployeesWithHistoryAuditAndNoAccountsOrPay(){await using var d=await Open();var s=S(d);var id=await s.StageAsync(Csv(A,B));await s.CommitAsync(id);var created=await d.Set<Employee>().Where(x=>x.Code.StartsWith("FIC-")).OrderBy(x=>x.Code).ToListAsync();Assert.Equal(2,created.Count);Assert.All(created,e=>{Assert.Equal(0,e.BasicSalary);Assert.Equal("",e.Iban);Assert.Equal("",e.NationalId);Assert.Equal(EmployeeStatus.Active,e.Status);});Assert.Empty(await d.Set<AppUser>().ToListAsync());Assert.Equal(2,await d.Set<StatusHistory>().CountAsync(x=>x.Reason=="Imported"));Assert.Equal(2,await d.Set<EmployeeAssignment>().CountAsync(x=>x.Reason=="Imported"));Assert.Contains(await d.Set<AuditLog>().ToListAsync(),x=>x.Action=="ImportCommit");var r=await s.ReconcileAsync(id);Assert.Equal(new ImportReconciliation(2,2,0),r);Assert.Equal("Committed",(await s.GetAsync(id))!.Status);}
 [Fact]public async Task CommitTwiceAndDiscardAfterCommitAreRejected(){await using var d=await Open();var s=S(d);var id=await s.StageAsync(Csv(A));await s.CommitAsync(id);await Assert.ThrowsAsync<DomainException>(()=>s.CommitAsync(id));await Assert.ThrowsAsync<DomainException>(()=>s.DiscardAsync(id));Assert.Equal(2,await d.Set<Employee>().CountAsync());}
 [Fact]public async Task StaleDataBlocksCommitWithoutPartialImport(){await using var d=await Open();var s=S(d);var id=await s.StageAsync(Csv(A,B));d.Add(new Employee{Code="FIC-B",FullName="Fictional racing",Email="race@example.local",HireDate=new DateTime(2026,1,1),BranchId=1,DepartmentId=1,JobTitleId=1});await d.SaveChangesAsync();await Assert.ThrowsAsync<DomainException>(()=>s.CommitAsync(id));Assert.Equal(0,await d.Set<Employee>().CountAsync(x=>x.Code=="FIC-A"));Assert.Equal("Staged",(await s.GetAsync(id))!.Status);}
 [Fact]public async Task PostWriteFailureRollsBackEveryEmployeeAndAllowsCleanRetry(){await using var d=await Open();var s=S(d);var id=await s.StageAsync(Csv(A,B));d.Fail=true;await Assert.ThrowsAsync<InvalidOperationException>(()=>s.CommitAsync(id));d.Fail=false;d.ChangeTracker.Clear();Assert.Equal(0,await d.Set<Employee>().CountAsync(x=>x.Code.StartsWith("FIC-")));Assert.Equal("Staged",(await s.GetAsync(id))!.Status);await s.CommitAsync(id);Assert.Equal(2,await d.Set<Employee>().CountAsync(x=>x.Code.StartsWith("FIC-")));}
 [Fact]public async Task DiscardDeletesBatchAndRowsAndAllowsRestage(){await using var d=await Open();var s=S(d);var id=await s.StageAsync(Csv(A));await s.DiscardAsync(id);Assert.Equal(0,await d.Set<EmployeeImportBatch>().CountAsync());Assert.Equal(0,await d.Set<StagedEmployeeRow>().CountAsync());Assert.NotEqual(0,await s.StageAsync(Csv(A)));}
 [Fact]public async Task RequiresEmployeeManagePermission(){await using var d=await Open();var s=S(d,false);await Assert.ThrowsAsync<DomainException>(()=>s.StageAsync(Csv(A)));await Assert.ThrowsAsync<DomainException>(()=>s.CommitAsync(1));await Assert.ThrowsAsync<DomainException>(()=>s.DiscardAsync(1));await Assert.ThrowsAsync<DomainException>(()=>s.ReconcileAsync(1));}
 [Fact]public async Task RollbackTerminatesImportedPeopleKeepsRecordsAndNeedsReason(){await using var d=await Open();var s=S(d);var id=await s.StageAsync(Csv(A,B));await Assert.ThrowsAsync<DomainException>(()=>s.RollbackAsync(id,"x"));await s.CommitAsync(id);await Assert.ThrowsAsync<DomainException>(()=>s.RollbackAsync(id," "));Assert.Equal(2,await s.RollbackAsync(id,"wrong file"));var people=await d.Set<Employee>().Where(x=>x.Code.StartsWith("FIC-")).ToListAsync();Assert.Equal(2,people.Count);Assert.All(people,e=>Assert.Equal(EmployeeStatus.Terminated,e.Status));Assert.Equal(2,await d.Set<StatusHistory>().CountAsync(x=>x.To==EmployeeStatus.Terminated&&x.Reason!.Contains("rolled back")));Assert.Equal(2,await d.Set<EmployeeAssignment>().CountAsync(x=>x.Reason=="Imported"));var b=(await s.GetAsync(id))!;Assert.Equal("RolledBack",b.Status);Assert.Equal("wrong file",b.RollbackReason);var r=await s.ReconcileAsync(id);Assert.Equal(2,r.Linked);await Assert.ThrowsAsync<DomainException>(()=>s.RollbackAsync(id,"again"));await Assert.ThrowsAsync<DomainException>(()=>s.CommitAsync(id));}
 [Fact]public async Task RollbackLeavesFinalStatusPeopleAndRejectsStagedBatchAndMissingPermission(){await using var d=await Open();var s=S(d);var id=await s.StageAsync(Csv(A,B));await Assert.ThrowsAsync<DomainException>(()=>s.RollbackAsync(id,"nothing committed"));await s.CommitAsync(id);var one=await d.Set<Employee>().FirstAsync(x=>x.Code=="FIC-A");one.Status=EmployeeStatus.Resigned;await d.SaveChangesAsync();Assert.Equal(1,await s.RollbackAsync(id,"wrong file"));Assert.Equal(EmployeeStatus.Resigned,(await d.Set<Employee>().FirstAsync(x=>x.Code=="FIC-A")).Status);await Assert.ThrowsAsync<DomainException>(()=>S(d,false).RollbackAsync(id,"x"));}
}
